import { useDataManagerValues } from '@genshin-optimizer/common/database-ui'
import { CardThemed } from '@genshin-optimizer/common/ui'
import { objKeyMap } from '@genshin-optimizer/common/util'
import type { BuildResult, Progress } from '@genshin-optimizer/game-opt/solver'
import { Solver } from '@genshin-optimizer/game-opt/solver'
import {
  allDiscSlotKeys,
  type DiscSlotKey,
} from '@genshin-optimizer/zzz/consts'
import { getTeamFrame0, type ICachedDisc } from '@genshin-optimizer/zzz/db'
import {
  OptConfigContext,
  OptConfigProvider,
  useCharacterContext,
  useDatabaseContext,
  useTeam,
} from '@genshin-optimizer/zzz/db-ui'
import { toTag } from '@genshin-optimizer/zzz/formula'
import { useZzzCalcContext } from '@genshin-optimizer/zzz/formula-ui'
import { createOptimizeConfig } from '@genshin-optimizer/zzz/solver'
import { getCharStat, getWengineStat } from '@genshin-optimizer/zzz/stats'
import { BuildsSelector, WorkerSelector } from '@genshin-optimizer/zzz/ui'
import CloseIcon from '@mui/icons-material/Close'
import TrendingUpIcon from '@mui/icons-material/TrendingUp'
import {
  Box,
  Button,
  CardContent,
  LinearProgress,
  Stack,
  Typography,
} from '@mui/material'
import {
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import { useTranslation } from 'react-i18next'
import { DiscFilter } from './DiscFilter'
import { StatFilterCard } from './StatFilterCard'
import { WengineFilter } from './WengineFilter'

export default function Optimize() {
  const { key: characterKey } = useCharacterContext()!
  const team = useTeam(characterKey)!
  const { database } = useDatabaseContext()
  const mate = team.teammates.find((t) => t.characterKey === characterKey)
  const optConfigId = mate?.optConfigId

  useEffect(() => {
    if (optConfigId) return
    const newOptConfigId = database.optConfigs.new({
      wEngineTypes: [getCharStat(characterKey).specialty],
    })
    database.teams.setTeammateOptConfigId(
      characterKey,
      characterKey,
      newOptConfigId
    )
  }, [optConfigId, characterKey, database.optConfigs, database.teams])

  if (!optConfigId) return null
  return (
    <OptConfigProvider optConfigId={optConfigId}>
      <OptimizeWrapper />
    </OptConfigProvider>
  )
}

function OptimizeWrapper() {
  const { t } = useTranslation('optimize')
  const { database } = useDatabaseContext()
  const calc = useZzzCalcContext()
  const { key: characterKey } = useCharacterContext()!
  const team = useTeam(characterKey)!
  const { ref } = getTeamFrame0(team)
  const [numWorkers, setNumWorkers] = useState(8)
  const [progress, setProgress] = useState<Progress | undefined>(undefined)
  const { optConfig, optConfigId } = useContext(OptConfigContext)
  const discs = useDataManagerValues(database.discs)
  const discsBySlot = useMemo(() => {
    const slotKeyMap = {
      4: optConfig.slot4,
      5: optConfig.slot5,
      6: optConfig.slot6,
    } as const
    const isFilteredSlot = (slotKey: DiscSlotKey): slotKey is '4' | '5' | '6' =>
      ['4', '5', '6'].includes(slotKey)

    return discs.reduce(
      (discsBySlot, disc) => {
        const { slotKey, mainStatKey, level, location } = disc
        if (level < optConfig.levelLow || level > optConfig.levelHigh)
          return discsBySlot
        if (location && !optConfig.useEquipped && location !== characterKey)
          return discsBySlot
        if (
          isFilteredSlot(slotKey) &&
          !slotKeyMap[slotKey].includes(mainStatKey)
        )
          return discsBySlot
        discsBySlot[disc.slotKey].push(disc)
        return discsBySlot
      },
      {
        1: [],
        2: [],
        3: [],
        4: [],
        5: [],
        6: [],
      } as Record<DiscSlotKey, ICachedDisc[]>
    )
  }, [
    optConfig.slot4,
    optConfig.slot5,
    optConfig.slot6,
    optConfig.levelLow,
    optConfig.levelHigh,
    optConfig.useEquipped,
    discs,
    characterKey,
  ])
  const wengines = useDataManagerValues(database.wengines)
  const filteredWengines = useMemo(() => {
    return wengines.filter(({ key, level, location }) => {
      // only return equipped wengine if not opting for wengine
      if (!optConfig.optWengine) return location === characterKey

      if (level < optConfig.wlevelLow || level > optConfig.wlevelHigh)
        return false
      if (
        location &&
        !optConfig.useEquippedWengine &&
        location !== characterKey
      )
        return false

      const { type } = getWengineStat(key)
      // filter by path
      if (!optConfig.wEngineTypes.includes(type)) return false
      return true
    })
  }, [
    characterKey,
    wengines,
    optConfig.wlevelLow,
    optConfig.wlevelHigh,
    optConfig.optWengine,
    optConfig.wEngineTypes,
    optConfig.useEquippedWengine,
  ])

  const [optimizing, setOptimizing] = useState(false)

  // Provides a function to cancel the work
  const cancelToken = useRef(() => {})
  //terminate worker when component unmounts
  useEffect(() => () => cancelToken.current(), [])

  const currentSolver = useRef<Solver<string> | null>(null)
  const cfg = useMemo(() => {
    if (!calc || !ref) return
    const resolvedTag = toTag(ref)
    if (!resolvedTag) return
    return createOptimizeConfig({
      characterKey,
      calc,
      frames: [{ tag: resolvedTag, multiplier: 1 }],
      statFilters: (optConfig.statFilters ?? []).filter((s) => !s.disabled),
      setFilter2: optConfig.setFilter2,
      setFilter4: optConfig.setFilter4,
      allowRainbow: optConfig.allowRainbow,
      wengines: filteredWengines,
      discsBySlot,
      numWorkers,
      numOfBuilds: optConfig.maxBuildsToShow,
      setProgress,
    })
  }, [
    calc,
    ref,
    optConfig.statFilters,
    optConfig.setFilter2,
    optConfig.setFilter4,
    optConfig.allowRainbow,
    optConfig.maxBuildsToShow,
    characterKey,
    filteredWengines,
    discsBySlot,
    numWorkers,
    setProgress,
  ])

  const onOptimize = useCallback(async () => {
    const cancelled = new Promise<void>((r) => (cancelToken.current = r))
    setProgress(undefined)
    setOptimizing(true)
    await new Promise<void>((resolve) => {
      requestAnimationFrame(() => setTimeout(resolve, 0))
    })

    cancelled.then(() => currentSolver.current?.terminate('user cancelled'))
    let optimizer: Solver<string> | undefined
    let results: BuildResult<string>[]
    try {
      if (!cfg) return
      currentSolver.current = optimizer = new Solver(cfg)
      results = await optimizer.results
      // a newer run replaced us, let it own the state
      if (currentSolver.current !== optimizer) return
    } catch {
      return
    } finally {
      // skip cleanup if a newer run replaced us
      if (currentSolver.current === optimizer) {
        currentSolver.current = null
        cancelToken.current = () => {}
        setOptimizing(false)
      }
    }
    // Save results to optConfig
    database.optConfigs.newOrSetGeneratedBuildList(optConfigId, {
      builds: results.map(({ ids, value }) => ({
        wengineId: ids[0],
        discIds: objKeyMap(allDiscSlotKeys, (_slot, index) => ids[index + 1]),
        value,
      })),
      buildDate: Date.now(),
    })
  }, [cfg, setProgress, database.optConfigs, optConfigId])

  const onCancel = useCallback(() => {
    cancelToken.current()
    setOptimizing(false)
    setProgress(undefined)
  }, [cancelToken, setProgress])

  return (
    <CardThemed>
      <CardContent>
        <Stack spacing={1}>
          <Box
            sx={{
              display: 'flex',
              gap: 1,
              flexWrap: 'wrap',
              '& .MuiPaper-root': { flexGrow: 1 },
            }}
          >
            <StatFilterCard />
            <WengineFilter wengines={filteredWengines} />
            <DiscFilter discsBySlot={discsBySlot} />
          </Box>

          {progress && <ProgressIndicator progress={progress} />}
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
            <BuildsSelector
              maxBuildsToShow={optConfig.maxBuildsToShow}
              optConfigId={optConfigId}
            />
            <WorkerSelector
              numWorkers={numWorkers}
              setNumWorkers={setNumWorkers}
            />
            <Button
              disabled={!cfg}
              onClick={optimizing ? onCancel : onOptimize}
              color={optimizing ? 'error' : 'primary'}
              startIcon={optimizing ? <CloseIcon /> : <TrendingUpIcon />}
            >
              {optimizing ? t('cancel') : t('optimize')}
            </Button>
          </Box>
        </Stack>
      </CardContent>
    </CardThemed>
  )
}

function Monospace({ value }: { value: number }): JSX.Element {
  const str = value.toLocaleString()
  return (
    <Box component="span" sx={{ fontFamily: 'Monospace', display: 'inline' }}>
      {str}
    </Box>
  )
}
function ProgressIndicator(props: { progress: Progress }) {
  const { t } = useTranslation('optimize')
  const { computed, remaining, skipped, total } = props.progress
  const unskipped = computed + remaining

  const unskippedRatio = Math.log1p(unskipped) / Math.log1p(total)
  const remRatio = (remaining / unskipped) * unskippedRatio
  return (
    <Box>
      <Typography>
        {t('computed')}: <Monospace value={computed} /> /{' '}
        <Monospace value={unskipped} />{' '}
      </Typography>
      <Typography>
        {t('computed + skipped')}: <Monospace value={computed + skipped} /> /{' '}
        <Monospace value={total} />
      </Typography>
      <LinearProgress // ideally, it should be | <computed> | <remaining> | <skipped> |
        variant="determinate"
        value={(1 - remRatio) * 100}
        sx={{ height: 10, borderRadius: 5 }}
      />
    </Box>
  )
}
